{"code":"import { getQuarters, listCompanies } from '../servers/earnings/index.js';

const usCompanies = ['AAPL', 'AMD', 'AMZN', 'CRM', 'GOOGL', 'INTU', 'META', 'MSFT', 'NVDA', 'ORCL', 'SHOP', 'SPCX'];

let maxDrop = { company: null, period_end: null, drop_pct: -Infinity };

for (const symbol of usCompanies) {
  const quarters = await getQuarters({ symbol, limit: 40 });

  // quarters are ordered from most recent to oldest
  for (let i = 0; i < quarters.length - 1; i++) {
    const current = quarters[i];
    const previous = quarters[i + 1]; // the quarter immediately before (older)

    if (current.revenue_usd_b !== null && previous.revenue_usd_b !== null && previous.revenue_usd_b > 0) {
      const dropPct = ((previous.revenue_usd_b - current.revenue_usd_b) / previous.revenue_usd_b) * 100;

      if (dropPct > maxDrop.drop_pct) {
        maxDrop = {
          company: symbol,
          period_end: current.period_end,
          drop_pct: dropPct,
          current_rev: current.revenue_usd_b,
          previous_rev: previous.revenue_usd_b
        };
      }
    }
  }
}

console.log(JSON.stringify(maxDrop, null, 2));
